python3 - <<'PYEOF'
import json, uuid

# Load definitions
defs = json.load(open('/tmp/defs.json'))

# Load the scaffolded flow to get its id, version, and manual-trigger definition
flow = json.load(open('/work/output/artifacts/skill-flow-hitl-quality-schema-design/VendorPOReview/VendorPOReview/VendorPOReview.flow'))

manual_trigger_def = flow['definitions'][0]
flow_id = flow['id']
flow_version = flow['version']
entry_point_id = flow['nodes'][0]['inputs']['entryPointId']

# Build the complete flow
new_flow = {
  "id": flow_id,
  "version": flow_version,
  "name": "VendorPOReview",
  "nodes": [
    # 1. Manual trigger (already scaffolded)
    {
      "id": "start",
      "type": "core.trigger.manual",
      "typeVersion": "1.0",
      "display": { "label": "Manual trigger" },
      "inputs": {
        "entryPointId": entry_point_id,
        "isDefaultEntryPoint": True
      },
      "outputs": {
        "output": {
          "type": "object",
          "description": "Data passed when manually triggering the process.",
          "source": "null",
          "var": "output"
        }
      }
    },
    # 2. Script node: fetch PO data (mock)
    {
      "id": "fetchPOData",
      "type": "core.action.script",
      "typeVersion": defs['script']['version'],
      "display": { "label": "Fetch PO Data" },
      "inputs": {
        "script": "return { poNumber: 'PO-2024-001', vendorName: 'Acme Supplies Inc.', totalAmount: 15000.00 };"
      },
      "outputs": {
        "output": {
          "type": "object",
          "description": "The return value of the script",
          "source": "=result.response",
          "var": "output"
        },
        "error": {
          "type": "object",
          "description": "Error information if the script fails",
          "source": "=Error",
          "var": "error"
        }
      }
    },
    # 3. HITL quick-form: procurement officer review
    {
      "id": "poReview",
      "type": "uipath.human-in-the-loop.quick-form",
      "typeVersion": "1.0",
      "display": { "label": "PO Review" },
      "inputs": {
        "schema": {
          "schemaId": str(uuid.uuid4()),
          "fields": [
            {
              "id": "poNumber",
              "label": "PO Number",
              "type": "text",
              "direction": "input",
              "binding": "vars.fetchPOData.output.poNumber"
            },
            {
              "id": "vendorName",
              "label": "Vendor Name",
              "type": "text",
              "direction": "input",
              "binding": "vars.fetchPOData.output.vendorName"
            },
            {
              "id": "totalAmount",
              "label": "Total Amount",
              "type": "number",
              "direction": "input",
              "binding": "vars.fetchPOData.output.totalAmount"
            },
            {
              "id": "decision",
              "label": "Decision",
              "type": "text",
              "direction": "output",
              "variable": "vars.officerDecision"
            },
            {
              "id": "notes",
              "label": "Notes (optional)",
              "type": "text",
              "direction": "output",
              "variable": "vars.officerNotes"
            }
          ],
          "outcomes": [
            {
              "id": "Approve",
              "name": "Approve",
              "type": "string",
              "isPrimary": True,
              "action": "Continue"
            },
            {
              "id": "Reject",
              "name": "Reject",
              "type": "string",
              "isPrimary": False,
              "action": "End"
            }
          ]
        },
        "recipient": {
          "channels": ["Email", "ActionCenter"],
          "connections": {},
          "assignee": { "type": "group" }
        },
        "priority": "High"
      },
      "outputs": {
        "output": {
          "type": "object",
          "description": "Task result data",
          "source": "=result",
          "var": "output",
          "properties": {
            "decision": { "type": "string" },
            "notes": { "type": "string" },
            "Action": {
              "type": "string",
              "enum": ["Approve", "Reject"],
              "default": "Approve"
            }
          }
        },
        "status": {
          "type": "string",
          "description": "Task completion status",
          "source": "=result.Action",
          "var": "status",
          "enum": ["Approve", "Reject"],
          "default": "Approve"
        }
      }
    },
    # 4. Decision node: route on officer decision
    {
      "id": "checkDecision",
      "type": "core.logic.decision",
      "typeVersion": defs['decision']['version'],
      "display": { "label": "Approved?" },
      "inputs": {
        "expression": "$vars.poReview.status === \"Approve\""
      }
    },
    # 5. Script node: log PO approved
    {
      "id": "logApproved",
      "type": "core.action.script",
      "typeVersion": defs['script']['version'],
      "display": { "label": "Log PO Approved" },
      "inputs": {
        "script": "return { message: 'PO approved', poNumber: $vars.fetchPOData.output.poNumber, notes: $vars.poReview.output.notes };"
      },
      "outputs": {
        "output": {
          "type": "object",
          "description": "The return value of the script",
          "source": "=result.response",
          "var": "output"
        },
        "error": {
          "type": "object",
          "description": "Error information if the script fails",
          "source": "=Error",
          "var": "error"
        }
      }
    },
    # 6. End node (approved path)
    {
      "id": "endApproved",
      "type": "core.control.end",
      "typeVersion": defs['end']['version'],
      "display": { "label": "End (Approved)" },
      "inputs": {}
    },
    # 7. End node (rejected path)
    {
      "id": "endRejected",
      "type": "core.control.end",
      "typeVersion": defs['end']['version'],
      "display": { "label": "End (Rejected)" },
      "inputs": {}
    }
  ],
  "edges": [
    {
      "id": "edge-start-fetchPOData",
      "sourceNodeId": "start",
      "sourcePort": "output",
      "targetNodeId": "fetchPOData",
      "targetPort": "input"
    },
    {
      "id": "edge-fetchPOData-poReview",
      "sourceNodeId": "fetchPOData",
      "sourcePort": "success",
      "targetNodeId": "poReview",
      "targetPort": "input"
    },
    {
      "id": "edge-poReview-checkDecision",
      "sourceNodeId": "poReview",
      "sourcePort": "outcome-completed",
      "targetNodeId": "checkDecision",
      "targetPort": "input"
    },
    {
      "id": "edge-checkDecision-logApproved",
      "sourceNodeId": "checkDecision",
      "sourcePort": "true",
      "targetNodeId": "logApproved",
      "targetPort": "input"
    },
    {
      "id": "edge-checkDecision-endRejected",
      "sourceNodeId": "checkDecision",
      "sourcePort": "false",
      "targetNodeId": "endRejected",
      "targetPort": "input"
    },
    {
      "id": "edge-logApproved-endApproved",
      "sourceNodeId": "logApproved",
      "sourcePort": "success",
      "targetNodeId": "endApproved",
      "targetPort": "input"
    }
  ],
  "definitions": [
    manual_trigger_def,
    defs['script'],
    defs['hitl'],
    defs['decision'],
    defs['end']
  ],
  "bindings": [],
  "variables": {
    "globals": [],
    "nodes": []
  },
  "layout": {
    "nodes": {
      "start":         { "position": { "x": 0,   "y": 0 }, "size": { "width": 96, "height": 96 }, "collapsed": False },
      "fetchPOData":   { "position": { "x": 0,   "y": 0 }, "size": { "width": 96, "height": 96 }, "collapsed": False },
      "poReview":      { "position": { "x": 0,   "y": 0 }, "size": { "width": 96, "height": 96 }, "collapsed": False },
      "checkDecision": { "position": { "x": 0,   "y": 0 }, "size": { "width": 96, "height": 96 }, "collapsed": False },
      "logApproved":   { "position": { "x": 0,   "y": 0 }, "size": { "width": 96, "height": 96 }, "collapsed": False },
      "endApproved":   { "position": { "x": 0,   "y": 0 }, "size": { "width": 96, "height": 96 }, "collapsed": False },
      "endRejected":   { "position": { "x": 0,   "y": 0 }, "size": { "width": 96, "height": 96 }, "collapsed": False }
    }
  }
}

with open('/work/output/artifacts/skill-flow-hitl-quality-schema-design/VendorPOReview/VendorPOReview/VendorPOReview.flow', 'w') as f:
    json.dump(new_flow, f, indent=2)

print('Flow written successfully')
PYEOF

